import { publishPolicy } from '@projexlight/sdk-policy';
await publishPolicy({
  tenant_id, name: 'admin-action-business-hours', version: '1.0.0',
  dsl: `rule "business-hours-only" {
    when resource.is_admin_action and not (now.hour >= 9 and now.hour < 17 and persona.tz_matches_tenant)
    then deny with reason "outside business hours"
  }`,
});

import { evaluatePolicy } from '@projexlight/sdk-policy';
const { decision, matched_rule } = await evaluatePolicy({
  tenant_id, policy: 'adaptive-mfa-step-up',
  attributes: { principal, action, resource, risk_score: await getRiskScore() },
});
if (decision === 'step-up') redirectToMfa();

// policy dsl:
//   rule "eu-residency" {
//     when resource.region == 'EU' and target.region != 'EU'
//     then deny with reason "EU data cannot leave EU region"
//   }
const { decision } = await evaluatePolicy({
  tenant_id, policy: 'eu-data-residency',
  attributes: { resource: { region: 'EU' }, target: { region: 'US' } },
});

import { registerFetcher } from '@projexlight/sdk-policy';
await registerFetcher({
  tenant_id, name: 'risk_score',
  source: { kind: 'sdk', call: '@projexlight/sdk-fraud.getScore', args: { principal_id: '$principal.id' } },
  cache_ttl_ms: 30_000,
});

import { startDecisionAuditor } from '@projexlight/sdk-policy';
startDecisionAuditor({
  tenant_id, replay_window_hours: 24,
  drift_alert_channel: 'oncall-compliance',
});
